    data class Variant3(val value: RecordVersionDtoVariant3) : RecordVersionDto { override fun toJson() = value.toJson() }
    data class Variant4(val value: RecordVersionDtoVariant4) : RecordVersionDto { override fun toJson() = value.toJson() }
    companion object { fun decode(value: JSONObject): RecordVersionDto {
        ContractChecks.check("RecordVersionDto", value)
        decodeOrNull { RecordVersionDtoVariant1.decode(value) }?.let { return Variant1(it) }
        decodeOrNull { RecordVersionDtoVariant2.decode(value) }?.let { return Variant2(it) }
        decodeOrNull { RecordVersionDtoVariant3.decode(value) }?.let { return Variant3(it) }
        decodeOrNull { RecordVersionDtoVariant4.decode(value) }?.let { return Variant4(it) }
        throw MobileContractViolation("Unsupported object variant")
    } }
}

