            `symbol` = if (value.has("symbol")) WireField.Present(string(value.get("symbol"))) else WireField.Absent,
            `quantity` = WireScalar.decode(value.get("quantity")),
            `price_vnd` = WireScalar.decode(value.get("price_vnd"))
        )
    } }
}

