sealed interface PreviewResultDto : MobileDto {
    data class Variant1(val value: PreviewResultDtoVariant1) : PreviewResultDto { override fun toJson() = value.toJson() }
    data class Variant2(val value: PreviewResultDtoVariant2) : PreviewResultDto { override fun toJson() = value.toJson() }
    companion object { fun decode(value: JSONObject): PreviewResultDto {
        ContractChecks.check("PreviewResultDto", value)
        decodeOrNull { PreviewResultDtoVariant1.decode(value) }?.let { return Variant1(it) }
        decodeOrNull { PreviewResultDtoVariant2.decode(value) }?.let { return Variant2(it) }
        throw MobileContractViolation("Unsupported object variant")
    } }
}

